compliant.code:
def main():
    return helper_function()  # OK: resolved when main() is called

def helper_function():
    return 42

# Both functions defined before main() is called
result = main()

previous = None
for i in range(5):
    if previous is not None:
        print(f"Previous: {previous}")
    previous = i
